# -*- coding: utf-8 -*-
"""Batch 3 (G014–G023): integrated English activities (CLIL) adapted from Trang Phan's Teaching Gallery."""
from games_batch2 import plan, vn, steps, ROW_SIZE, ROW_TIME

G = []
def add(**k): G.append(k)

def mk(id, slug, src, en, vi, skills, levels, step, cefr, grades, time, size, prep, mode, board, lines, cards, program, strand, exp,
       why, st, gp, vnp, tip, meta):
    add(id=id, slug=slug, status="pilot", nguon=src, ten_EN=en, ten_VI=vi, ky_nang=skills, trinh_do=levels, step_level=step, cefr=cefr,
        khoi_lop=grades, thoi_luong=time, si_so=size, thiet_bi="no", chuan_bi_EN=prep[0], chuan_bi_VI=prep[1], kieu_video=mode,
        minh_hoa_bang=board, minh_hoa_loi=lines, minh_hoa_the=cards, ontario_program=program, ontario_strand=strand,
        ontario_expectation=exp, the_why_EN=why[0], the_why_VI=why[1], cac_buoc_EN=steps(st[0]), cac_buoc_VI=steps(st[1]),
        giao_an_EN=plan("en", *gp[0]), giao_an_VI=plan("vi", *gp[1]), goc_nhin_VN_EN=vn("en", *vnp[0]), goc_nhin_VN_VI=vn("vi", *vnp[1]),
        pro_tip_EN=tip[0], pro_tip_VI=tip[1], meta_EN=meta[0], meta_VI=meta[1])

R3 = lambda en, vi: ([ROW_SIZE["en"], ROW_TIME["en"], en], [ROW_SIZE["vi"], ROW_TIME["vi"], vi])

